import struct, json

data = open('/app/trunc.db','rb').read()
print("file size", len(data))

def read_varint(buf, off):
    result = 0
    for i in range(9):
        b = buf[off+i]
        if i == 8:
            result = (result << 8) | b
        else:
            result = (result << 7) | (b & 0x7f)
        if not (b & 0x80):
            return result, off+i+1
    return result, off+9

def parse_page(buf, page_off):
    ptype = buf[page_off]
    if ptype not in (0x0d, 0x05, 0x0a, 0x02):
        return None
    ncells = int.from_bytes(buf[page_off+3:page_off+5], 'big')
    ptr_off = page_off + 8
    if ptype in (0x05, 0x02):
        ptr_off = page_off + 12
    cells = []
    for i in range(ncells):
        coff = int.from_bytes(buf[ptr_off+i*2:ptr_off+i*2+2], 'big')
        cells.append(coff)
    return cells

cells = parse_page(data, 0)
if cells is None:
    cells = parse_page(data, 100)
print("cells:", cells)

def decode_serial(buf, types, data_off):
    cols = []
    for t in types:
        if t == 0:
            cols.append(None)
        elif t == 1:
            cols.append(int.from_bytes(buf[data_off:data_off+1], 'big', signed=True)); data_off+=1
        elif t == 2:
            cols.append(int.from_bytes(buf[data_off:data_off+2], 'big', signed=True)); data_off+=2
        elif t == 3:
            cols.append(int.from_bytes(buf[data_off:data_off+3], 'big', signed=True)); data_off+=3
        elif t == 4:
            cols.append(int.from_bytes(buf[data_off:data_off+4], 'big', signed=True)); data_off+=4
        elif t == 5:
            cols.append(int.from_bytes(buf[data_off:data_off+6], 'big', signed=True)); data_off+=6
        elif t == 6:
            cols.append(int.from_bytes(buf[data_off:data_off+8], 'big', signed=True)); data_off+=8
        elif t == 7:
            cols.append(struct.unpack('>d', buf[data_off:data_off+8])[0]); data_off+=8
        elif t == 8:
            cols.append(0)
        elif t == 9:
            cols.append(1)
        elif t >= 12:
            if t % 2 == 0:
                ln = (t-12)//2
                cols.append(buf[data_off:data_off+ln]); data_off+=ln
            else:
                ln = (t-13)//2
                cols.append(buf[data_off:data_off+ln].decode('utf-8', errors='replace')); data_off+=ln
        else:
            cols.append(None)
    return cols

results = []
for coff in cells:
    off = coff
    payload_len, off = read_varint(data, off)
    rowid, off = read_varint(data, off)
    hdr_size, hoff = read_varint(data, off)
    types = []
    p = hoff
    while p < off + hdr_size:
        t, p = read_varint(data, p)
        types.append(t)
    cols = decode_serial(data, types, p)
    print("rowid", rowid, "cols", cols, "payload_len", payload_len)
    word = None; value = None
    for c in cols:
        if isinstance(c, str) and word is None:
            word = c
        elif isinstance(c, (int, float)) and value is None:
            value = c
    if word is not None:
        results.append((rowid, word, value))

results.sort(key=lambda x: x[0])
out = [{"word": w, "value": (int(v) if isinstance(v,float) and v.is_integer() else v)} for _,w,v in results]
print(json.dumps(out, indent=2))
EOF
